WITH FilteredEmployees AS (SELECT * FROM employees WHERE job_title IN ('Manager', 'Intern', 'Engineer') AND salary > 112000), EmployeesStats AS (SELECT CASE WHEN job_title IN ('Designer', 'Manager') THEN 'priority' ELSE 'other' END AS job_title_group, COUNT(CASE WHEN job_title = 'Analyst' THEN 1 END) AS analyst_count, ROUND((100 * SUM(CASE WHEN job_title = 'Manager' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_manager FROM FilteredEmployees GROUP BY CASE WHEN job_title IN ('Designer', 'Manager') THEN 'priority' ELSE 'other' END) SELECT * FROM EmployeesStats WHERE pct_manager >= 59 ORDER BY analyst_count DESC
